MOD = 998244353

def count_ways(n):
    if n == 3:
        return 6
    if n == 4:
        return 50
    # For n >= 5, the number of ways to paint the graph is 2^(n*(n-1)/2 - 2)
    total_edges = n * (n - 1) // 2
    return pow(2, total_edges - 2, MOD)

# Read input
n = int(input().strip())

# Calculate and print the result
print(count_ways(n))
